# Standardise prose typography without altering paths, IDs, URLs or literal authority quotations.
def fix(t):
 t=re.sub(r'([A-Za-z])(?=\d)',r'\1 ',t);t=re.sub(r'(\d)(?=[A-Za-z])',r'\1 ',t);t=re.sub(r'([A-Za-z])(?=\$)',r'\1 ',t);return t

def walk(x,k=''):
 if isinstance(x,list):return [walk(v,k) for v in x]
 if isinstance(x,dict):return {a:walk(b,a) for a,b in x.items()}
 if isinstance(x,str) and k in ('title','description','heading','paragraphs','bullets','headers','rows','practicalOutput','limitations','notes'):return fix(x)
 return x
guides=walk(guides);rules=walk(rules)
for s in sources:
 for k in ('title','section','notes'):s[k]=fix(s[k])
for name,records in [('blocked-guides',guides)]: (out/(name+'.json')).write_text(json.dumps(records,indent=2,ensure_ascii=False)+'\n')
(data/'batch2-blocked-sources.json').write_text(json.dumps(sources,indent=2,ensure_ascii=False)+'\n')
(data/'batch2-blocked-rules.json').write_text(json.dumps(rules,indent=2,ensure_ascii=False)+'\n')
